#[rustfmt::skip]
impl SsaTerm for MTerm {
    fn indirect_target(&self) -> Option<Self::Reg> {
        match self {
            Self::Indirect { target, .. } => Some(*target),
            Self::B { .. } => None,
            Self::BCond { .. } => None,
            Self::Cb { .. } => None,
            Self::Tb { .. } => None,
            Self::Ret { .. } => None,
            Self::Brk { .. } => None,
            Self::AsmGoto { .. } => None,
        }
    }

    fn set_indirect_target(&mut self, reg: Self::Reg) {
        match self {
            Self::Indirect { target, .. } => *target = reg,
            Self::B { .. } => {},
            Self::BCond { .. } => {},
            Self::Cb { .. } => {},
            Self::Tb { .. } => {},
            Self::Ret { .. } => {},
            Self::Brk { .. } => {},
            Self::AsmGoto { .. } => {},
        }
    }

    fn clear_edge_args(&mut self) {
        match self {
            Self::Indirect { edges, .. } => { for (_, args) in edges { args.clear(); } },
            Self::B { args, .. } => { args.clear(); },
            Self::BCond { taken_args, untaken_args, .. } => { taken_args.clear(); untaken_args.clear(); },
            Self::Cb { taken_args, untaken_args, .. } => { taken_args.clear(); untaken_args.clear(); },
            Self::Tb { taken_args, untaken_args, .. } => { taken_args.clear(); untaken_args.clear(); },
            Self::Ret { .. } => {},
            Self::Brk { .. } => {},
            Self::AsmGoto { fallthrough_args, labels, .. } => { for (_, args) in labels { args.clear(); } fallthrough_args.clear(); },
        }
    }

    fn retarget(&mut self, from: usize, to: u32) {
        let mut index = 0;
        let mut visit = |target: &mut u32, args: &mut Vec<VReg>| {
            if index == from {
                *target = to;
                args.clear();
            }
            index += 1;
        };
        match self {
            Self::Indirect { .. } => unreachable!("computed edges cannot be retargeted without address routing"),
            Self::B { args, target, .. } => { visit(target, args); },
            Self::BCond { taken, taken_args, untaken, untaken_args, .. } => { visit(taken, taken_args); visit(untaken, untaken_args); },
            Self::Cb { taken, taken_args, untaken, untaken_args, .. } => { visit(taken, taken_args); visit(untaken, untaken_args); },
            Self::Tb { taken, taken_args, untaken, untaken_args, .. } => { visit(taken, taken_args); visit(untaken, untaken_args); },
            Self::Ret { .. } => {},
            Self::Brk { .. } => {},
            Self::AsmGoto { fallthrough, fallthrough_args, labels, .. } => { for (target, args) in labels { visit(target, args); } visit(fallthrough, fallthrough_args); },
        }
    }

    fn jump(target: u32, args: Vec<Self::Reg>) -> Self {
        Self::B { target, args }
    }

    fn prevents_forwarding(&self) -> bool {
        match self {
            Self::Indirect { .. } => true,
            Self::B { .. } => false,
            Self::BCond { .. } => false,
            Self::Cb { .. } => false,
            Self::Tb { .. } => false,
            Self::Ret { .. } => false,
            Self::Brk { .. } => false,
            Self::AsmGoto { body, .. } => body.numbered().iter().any(|operand| operand.fixed_register.is_some()),
        }
    }
}

